from ute_common_abstract_core.network_elem_identification import CellIdentification


class LteCell:
    """LTE cell object"""

    def __init__(self, identification):
        """
        Wrap object for easy handling of ute_common_abstract_core.network_elem_identification.CellIdentification.

        :param identification: encapsulated CELL description
        :type: CellIdentification
        """
        LteCell._verify_cell_id_type(identification)
        LteCell._verify_cell_id_contains_infomodel_key_with_proper_dict(identification)
        self._identification = identification

    def get_cell_id(self):
        """
        :return: {'cell_id': 'id', 'enb_id': 'id'}
        :rtype: dict
        """
        return self._identification.get('infomodel', {})

    def start_collecting_cell_statistics(self):
        """
        Start collecting cell statistics
        :return:
        """
        raise NotImplementedError

    def stop_collecting_cell_statistics(self):
        """
        Stop collecting cell statistics
        :return:
        """
        raise NotImplementedError

    def get_throughput(self, direction, function, type):
        """
        Return cell throughput in bps
        :param direction: "dl" or "ul"
        :param function: one of "maximum", "minimum", "average", "current"
        :param type: one of "data", "signalling", "SRB1"
        :return:
        """
        raise NotImplementedError

    def verify_throughput(self, tput_min, tput_max=None, direction="dl", function="current", type="data"):
        """
        :param tput_min:
        :param tput_max:
        :param direction: "dl" or "ul"
        :param function: one of "maximum", "minimum", "average", "current"
        :param type: one of "data", "signalling", "SRB1"
        :return:
        """
        raise NotImplementedError

    @staticmethod
    def _verify_cell_id_type(real_id):
        if not isinstance(real_id, CellIdentification):
            raise AttributeError(f'{real_id} is not CellIdentification instace, but: {real_id.__class__.__name__}')

    @staticmethod
    def _verify_cell_id_contains_infomodel_key_with_proper_dict(real_id):
        if 'infomodel' not in real_id:
            raise KeyError("CellIdentification does not contain >infomodel< key")
        infomodel_value = real_id.get('infomodel', {})
        if 'cell_id' not in infomodel_value or 'enb_id' not in infomodel_value:
            raise KeyError("CellIdentification does not contain dict with expected keys: enb_id, cell_id")

    def __repr__(self):
        return f'{self.__class__.__name__}({self.get_cell_id()})'
